<?php

namespace MongoDB\Driver;

use MongoDB\BSON\Timestamp;
use MongoDB\BSON\TimestampInterface;
use MongoDB\Driver\Exception\CommandException;
use MongoDB\Driver\Exception\InvalidArgumentException;

/**
 * <div id="class.mongodb-driver-session" class="reference"> <h1 class="title">The MongoDB\Driver\Session class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.4.0)</p>  <div class="section" id="mongodb-driver-session.intro">   <h2 class="title">简介</h2>   <p class="simpara">    The <span class="classname"><strong class="classname">MongoDB\Driver\Session</strong></span> class represents a    client session and is returned by    <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::startSession()}</span>. Commands,    queries, and write operations may then be associated with the session.   </p>  </div>  <div class="section" id="mongodb-driver-session.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\Session</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php#mongodb-driver-session.constants.transaction-none"><var class="varname">TRANSACTION_NONE</var></a></var><span class="initializer"> = none</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php#mongodb-driver-session.constants.transaction-starting"><var class="varname">TRANSACTION_STARTING</var></a></var><span class="initializer"> = starting</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php#mongodb-driver-session.constants.transaction-in-progress"><var class="varname">TRANSACTION_IN_PROGRESS</var></a></var><span class="initializer"> = in_progress</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php#mongodb-driver-session.constants.transaction-committed"><var class="varname">TRANSACTION_COMMITTED</var></a></var><span class="initializer"> = committed</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php#mongodb-driver-session.constants.transaction-aborted"><var class="varname">TRANSACTION_ABORTED</var></a></var><span class="initializer"> = aborted</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.aborttransaction.php" class="methodname" style="color:#CC7832">abortTransaction</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.advanceclustertime.php" class="methodname" style="color:#CC7832">advanceClusterTime</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$clusterTime</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.advanceoperationtime.php" class="methodname" style="color:#CC7832">advanceOperationTime</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-timestampinterface.php" class="type MongoDB\BSON\TimestampInterface" style="color:#EAB766">MongoDB\BSON\TimestampInterface</a></span> <span class="parameter" style="color:#3A95FF">\$operationTime</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.committransaction.php" class="methodname" style="color:#CC7832">commitTransaction</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">private</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>()</div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.endsession.php" class="methodname" style="color:#CC7832">endSession</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.getclustertime.php" class="methodname" style="color:#CC7832">getClusterTime</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.getlogicalsessionid.php" class="methodname" style="color:#CC7832">getLogicalSessionId</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.getoperationtime.php" class="methodname" style="color:#CC7832">getOperationTime</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-timestamp.php" class="type MongoDB\BSON\Timestamp" style="color:#EAB766">MongoDB\BSON\Timestamp</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.getserver.php" class="methodname" style="color:#CC7832">getServer</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="type MongoDB\Driver\Server" style="color:#EAB766">MongoDB\Driver\Server</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.gettransactionoptions.php" class="methodname" style="color:#CC7832">getTransactionOptions</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.gettransactionstate.php" class="methodname" style="color:#CC7832">getTransactionState</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.isdirty.php" class="methodname" style="color:#CC7832">isDirty</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.isintransaction.php" class="methodname" style="color:#CC7832">isInTransaction</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-session.starttransaction.php" class="methodname" style="color:#CC7832">startTransaction</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>    <div class="section" id="mongodb-driver-session.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-driver-session.constants.transaction-none"><strong><span>{@link MongoDB\Driver\Session::TRANSACTION_NONE}</span></strong></dt>     <dd>      <span class="simpara">       There is no transaction in progress.      </span>     </dd>             <dt id="mongodb-driver-session.constants.transaction-starting"><strong><span>{@link MongoDB\Driver\Session::TRANSACTION_STARTING}</span></strong></dt>     <dd>      <span class="simpara">       A transaction has been started, but no operation has been sent to the server.      </span>     </dd>             <dt id="mongodb-driver-session.constants.transaction-in-progress"><strong><span>{@link MongoDB\Driver\Session::TRANSACTION_IN_PROGRESS}</span></strong></dt>     <dd>      <span class="simpara">       A transaction is in progress.      </span>     </dd>             <dt id="mongodb-driver-session.constants.transaction-committed"><strong><span>{@link MongoDB\Driver\Session::TRANSACTION_COMMITTED}</span></strong></dt>     <dd>      <span class="simpara">       The transaction was committed.      </span>     </dd>             <dt id="mongodb-driver-session.constants.transaction-aborted"><strong><span>{@link MongoDB\Driver\Session::TRANSACTION_ABORTED}</span></strong></dt>     <dd>      <span class="simpara">       The transaction was aborted.      </span>     </dd>       </dl>  </div>   </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\Session::abortTransaction} — Aborts a transaction</li><li>{@link MongoDB\Driver\Session::advanceClusterTime} — Advances the cluster time for this session</li><li>{@link MongoDB\Driver\Session::advanceOperationTime} — Advances the operation time for this session</li><li>{@link MongoDB\Driver\Session::commitTransaction} — Commits a transaction</li><li>{@link MongoDB\Driver\Session::__construct} — Create a new Session (not used)</li><li>{@link MongoDB\Driver\Session::endSession} — Terminates a session</li><li>{@link MongoDB\Driver\Session::getClusterTime} — Returns the cluster time for this session</li><li>{@link MongoDB\Driver\Session::getLogicalSessionId} — Returns the logical session ID for this session</li><li>{@link MongoDB\Driver\Session::getOperationTime} — Returns the operation time for this session</li><li>{@link MongoDB\Driver\Session::getServer} — Returns the server to which this session is pinned</li><li>{@link MongoDB\Driver\Session::getTransactionOptions} — Returns options for the currently running transaction</li><li>{@link MongoDB\Driver\Session::getTransactionState} — Returns the current transaction state for this session</li><li>{@link MongoDB\Driver\Session::isDirty} — Returns whether the session has been marked as dirty</li><li>{@link MongoDB\Driver\Session::isInTransaction} — Returns whether a multi-document transaction is in progress</li><li>{@link MongoDB\Driver\Session::startTransaction} — Starts a transaction</li></ul></div>
 * 
 * Class Session
 *
 * @link https://secure.php.net/manual/en/class.mongodb-driver-session.php
 * @since 1.4.0
 */
final class Session
{
    /**
     * @since 1.7.0
     */
    public const TRANSACTION_NONE = 'none';

    /**
     * @since 1.7.0
     */
    public const TRANSACTION_STARTING = 'starting';

    /**
     * @since 1.7.0
     */
    public const TRANSACTION_IN_PROGRESS = 'in_progress';

    /**
     * @since 1.7.0
     */
    public const TRANSACTION_COMMITTED = 'committed';

    /**
     * @since 1.7.0
     */
    public const TRANSACTION_ABORTED = 'aborted';

    /**
 * <div id="mongodb-driver-session.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.4.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::__construct</span> — <span class="dc-title">Create a new Session (not used)</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">private</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::__construct</strong></span>()</div>  <p class="simpara">   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php" class="classname">MongoDB\Driver\Session</a></span> objects are returned by   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::startSession()}</span> and cannot be   constructed directly.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.construct-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Manager::startSession()} - Start a new client session for use with this client</span></li>  </ul> </div></div>
 * 
     * Create a new Session (not used)
     * @link https://secure.php.net/manual/en/mongodb-driver-session.construct.php
     * @since 1.4.0
     */
    final private function __construct() {}


    final public function __wakeup() {}

    /**
 * <div id="mongodb-driver-session.aborttransaction" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::abortTransaction</h1>  <p class="verinfo">(mongodb &gt;=1.5.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::abortTransaction</span> — <span class="dc-title">Aborts a transaction</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.aborttransaction-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::abortTransaction</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Terminates the multi-document transaction and rolls back any data changes   made by the operations within the transaction. That is, the transaction ends   without saving any of the changes made by the operations in the transaction.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.aborttransaction-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.aborttransaction-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.aborttransaction-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if the transaction could not be aborted (e.g. a transaction was not started).</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.aborttransaction-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::startSession()} - Start a new client session for use with this client</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::commitTransaction()} - Commits a transaction</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::startTransaction()} - Starts a transaction</span></li>  </ul> </div></div>
 * 
     * Aborts a transaction
     * @link https://secure.php.net/manual/en/mongodb-driver-session.aborttransaction.php
     * @since 1.5.0
     */
    final public function abortTransaction(): void {}

    /**
 * <div id="mongodb-driver-session.advanceclustertime" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::advanceClusterTime</h1>  <p class="verinfo">(mongodb &gt;=1.4.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::advanceClusterTime</span> — <span class="dc-title">Advances the cluster time for this session</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.advanceclustertime-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::advanceClusterTime</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$clusterTime</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Advances the cluster time for this session. If the cluster time is less than   or equal to the session's current cluster time, this function is a no-op.  </p>  <p class="simpara">   By using this method in conjunction with   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::advanceOperationTime()}</span> to copy   the cluster and operation times from another session, you can ensure that   operations in this session are causally consistent with the last operation in   the other session.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.advanceclustertime-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">clusterTime</span></dt>    <dd>     <span class="simpara">      The cluster time is a document containing a logical timestamp and server      signature. Typically, this value will be obtained by calling      <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::getClusterTime()}</span> on another      session object.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.advanceclustertime-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.advanceclustertime-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.advanceclustertime-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::advanceOperationTime()} - Advances the operation time for this session</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::getClusterTime()} - Returns the cluster time for this session</span></li>  </ul> </div></div>
 * 
     * Advances the cluster time for this session
     * @link https://secure.php.net/manual/en/mongodb-driver-session.advanceclustertime.php
     * @param array|object $clusterTime The cluster time is a document containing a logical timestamp and server signature
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException On argument parsing errors
     * @since 1.4.0
     */
    final public function advanceClusterTime(array|object $clusterTime): void {}

    /**
 * <div id="mongodb-driver-session.advanceoperationtime" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::advanceOperationTime</h1>  <p class="verinfo">(mongodb &gt;=1.4.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::advanceOperationTime</span> — <span class="dc-title">Advances the operation time for this session</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.advanceoperationtime-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::advanceOperationTime</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-timestampinterface.php" class="type MongoDB\BSON\TimestampInterface" style="color:#EAB766">MongoDB\BSON\TimestampInterface</a></span> <span class="parameter" style="color:#3A95FF">\$operationTime</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Advances the operation time for this session. If the operation time is less   than or equal to the session's current operation time, this function is a   no-op.  </p>  <p class="simpara">   By using this method in conjunction with   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::advanceClusterTime()}</span> to copy   the operation and cluster times from another session, you can ensure that   operations in this session are causally consistent with the last operation in   the other session.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.advanceoperationtime-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">operationTime</span></dt>    <dd>     <span class="simpara">      The operation time is a logical timestamp. Typically, this value will be      obtained by calling      <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::getOperationTime()}</span> on      another session object.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.advanceoperationtime-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.advanceoperationtime-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.advanceoperationtime-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::advanceClusterTime()} - Advances the cluster time for this session</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::getClusterTime()} - Returns the cluster time for this session</span></li>  </ul> </div></div>
 * 
     * Advances the operation time for this session
     * @link https://secure.php.net/manual/en/mongodb-driver-session.advanceoperationtime.php
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException On argument parsing errors
     * @since 1.4.0
