    final public function advanceOperationTime(TimestampInterface $operationTime): void {}

    /**
 * <div id="mongodb-driver-session.committransaction" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::commitTransaction</h1>  <p class="verinfo">(mongodb &gt;=1.5.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::commitTransaction</span> — <span class="dc-title">Commits a transaction</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.committransaction-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::commitTransaction</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Saves the changes made by the operations in the multi-document transaction   and ends the transaction. Until the commit, none of the data changes made   from within the transaction are visible outside the transaction.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.committransaction-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.committransaction-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.committransaction-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-commandexception.php" class="classname">MongoDB\Driver\Exception\CommandException</a></span> if the   server could not commit the transaction (e.g. due to conflicts, network   issues). In case the exception's   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Exception\CommandException::getResultDocument()}</span>   has a <span class="literal">"errorLabels"</span> element, and this array contains a   <span class="literal">"TransientTransactionError"</span> or   <span class="literal">"UnknownTransactionCommitResult"</span> value, it is safe to re-try   the <em>whole</em> transaction. In newer versions of the   extension,   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Exception\RuntimeException::hasErrorLabel()}</span>   should be used to test for this situation instead.</li>   <li>Throws   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if the   transaction could not be committed (e.g. a transaction was not   started).</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.committransaction-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::startSession()} - Start a new client session for use with this client</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::abortTransaction()} - Aborts a transaction</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::startTransaction()} - Starts a transaction</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Exception\RuntimeException::hasErrorLabel()} - Returns whether an error label is associated with an exception</span></li>  </ul> </div></div>
 * 
     * @link https://secure.php.net/manual/en/mongodb-driver-session.committransaction.php
     * @throws InvalidArgumentException On argument parsing errors
     * @throws CommandException If the server could not commit the transaction (e.g. due to conflicts,
     * network issues). In case the exception's MongoDB\Driver\Exception\CommandException::getResultDocument() has a "errorLabels"
     * element, and this array contains a "TransientTransactionError" or "UnUnknownTransactionCommitResult" value, it is safe to
     * re-try the whole transaction. In newer versions of the driver, MongoDB\Driver\Exception\RuntimeException::hasErrorLabel()
     * should be used to test for this situation instead.
     * @throws \MongoDB\Driver\Exception\RuntimeException If the transaction could not be committed (e.g. a transaction was not started)
     * @since 1.5.0
     */
    final public function commitTransaction(): void {}

    /**
 * <div id="mongodb-driver-session.endsession" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::endSession</h1>  <p class="verinfo">(mongodb &gt;=1.5.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::endSession</span> — <span class="dc-title">Terminates a session</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.endsession-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::endSession</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   This method closes an existing session. If a transaction was associated   with this session, the transaction will be aborted. After calling this   method, applications should not invoke other methods on the session.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    Sessions are also closed during garbage collection. It should not be    necessary to call this method under normal circumstances.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.endsession-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.endsession-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.endsession-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.endsession-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::startSession()} - Start a new client session for use with this client</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::abortTransaction()} - Aborts a transaction</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::commitTransaction()} - Commits a transaction</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::startTransaction()} - Starts a transaction</span></li>  </ul> </div></div>
 * 
     * This method closes an existing session. If a transaction was associated with this session, this transaction is also aborted,
     * and all its operations are rolled back.
     *
     * @link https://secure.php.net/manual/en/mongodb-driver-session.endsession.php
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException On argument parsing errors
     * @since 1.5.0
     */
    final public function endSession(): void {}

    /**
 * <div id="mongodb-driver-session.getclustertime" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::getClusterTime</h1>  <p class="verinfo">(mongodb &gt;=1.4.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::getClusterTime</span> — <span class="dc-title">Returns the cluster time for this session</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.getclustertime-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::getClusterTime</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></div>  <p class="simpara">   Returns the cluster time for this session. If the session has not been used   for any operation and   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::advanceClusterTime()}</span> has not   been called, the cluster time will be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.getclustertime-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.getclustertime-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the cluster time for this session, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if the session has no   cluster time.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.getclustertime-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.getclustertime-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::advanceClusterTime()} - Advances the cluster time for this session</span></li>  </ul> </div></div>
