    /**
 * <div id="mongodb-driver-session.getserver" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::getServer</h1>  <p class="verinfo">(mongodb &gt;=1.6.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::getServer</span> — <span class="dc-title">Returns the server to which this session is pinned</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.getserver-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::getServer</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="type MongoDB\Driver\Server" style="color:#EAB766">MongoDB\Driver\Server</a></span></span></div>  <p class="simpara">   Returns the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span> to which this   session is pinned. If the session is not pinned to a server, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> will be   returned.  </p>  <p class="simpara">   Session pinning is primarily used for sharded transactions, as all commands   within a sharded transaction must be sent to the same mongos instance. This   method is intended to be used by libraries built atop the extension to allow   use of a pinned server instead of invoking server selection.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.getserver-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.getserver-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span> to which this   session is pinned, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if the session is not pinned to any server.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.getserver-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div></div>
 * 
     * Returns the server to which this session is pinned, or NULL if the session is not pinned to any server.
     * @link https://secure.php.net/manual/en/mongodb-driver-session.getserver.php
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException
     * @since 1.6.0
     */
    final public function getServer(): ?Server {}

    /**
 * <div id="mongodb-driver-session.gettransactionoptions" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::getTransactionOptions</h1>  <p class="verinfo">(mongodb &gt;=1.7.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::getTransactionOptions</span> — <span class="dc-title">Returns options for the currently running transaction</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.gettransactionoptions-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::getTransactionOptions</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span></div>  <p class="simpara">   Returns options for the currently running transaction.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.gettransactionoptions-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.gettransactionoptions-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> containing current transaction options, or   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if no transaction is running.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.gettransactionoptions-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.gettransactionoptions-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::getTransactionState()} - Returns the current transaction state for this session</span></li>  </ul> </div></div>
 * 
     * Returns options for the current transactions, or NULL if no transaction is running.
     * @link https://secure.php.net/manual/en/mongodb-driver-session.gettransactionoptions.php
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException
     * @since 1.7.0
     */
    final public function getTransactionOptions(): ?array {}

    /**
 * <div id="mongodb-driver-session.gettransactionstate" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::getTransactionState</h1>  <p class="verinfo">(mongodb &gt;=1.7.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::getTransactionState</span> — <span class="dc-title">Returns the current transaction state for this session</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.gettransactionstate-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::getTransactionState</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Returns the transaction state for this session.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.gettransactionstate-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.gettransactionstate-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the current transaction state for this session.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.gettransactionstate-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.gettransactionstate-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::isInTransaction()} - Returns whether a multi-document transaction is in progress</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::getTransactionOptions()} - Returns options for the currently running transaction</span></li>  </ul> </div></div>
 * 
     * Returns the current transaction state
     * @link https://secure.php.net/manual/en/mongodb-driver-session.gettransactionstate.php
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException
     * @since 1.7.0
     */
    final public function getTransactionState(): string {}

    /**
 * <div id="mongodb-driver-session.isdirty" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::isDirty</h1>  <p class="verinfo">(mongodb &gt;=1.13.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::isDirty</span> — <span class="dc-title">Returns whether the session has been marked as dirty</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.isdirty-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::isDirty</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Returns whether the session has been marked as dirty (i.e. it has been used   with a command that encountered a network error).  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.isdirty-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.isdirty-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns whether the session has been marked as dirty.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.isdirty-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div></div>
 * 
     * Returns whether the session has been marked as dirty
     * @link https://www.php.net/manual/en/mongodb-driver-session.isdirty.php
     * @since 1.13.0
     */
    final public function isDirty(): bool {}

    /**
 * <div id="mongodb-driver-session.isintransaction" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::isInTransaction</h1>  <p class="verinfo">(mongodb &gt;=1.6.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::isInTransaction</span> — <span class="dc-title">Returns whether a multi-document transaction is in progress</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.isintransaction-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::isInTransaction</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Returns whether a multi-document transaction is currently in progress for   this session. A transaction is considered "in progress" if it has been   started but has not been committed or aborted.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.isintransaction-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.isintransaction-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if a transaction is currently in progress for this session,   and <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.isintransaction-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.isintransaction-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::getTransactionState()} - Returns the current transaction state for this session</span></li>  </ul> </div></div>
 * 
     * Returns whether a multi-document transaction is in progress.
     * @link https://secure.php.net/manual/en/mongodb-driver-session.isintransaction.php
     * @return bool
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException
     * @since 1.6.0
     */
    final public function isInTransaction(): bool {}

    /**
 * <div id="mongodb-driver-session.starttransaction" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Session::startTransaction</h1>  <p class="verinfo">(mongodb &gt;=1.5.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Session::startTransaction</span> — <span class="dc-title">Starts a transaction</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-session.starttransaction-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Session::startTransaction</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Starts a multi-document transaction associated with the session. At any given   time, you can have at most one open transaction for a session. After starting   a transaction, the session object must be passed to each operation via   the <span class="literal">"session"</span> option (e.g.   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()}</span>) in order   to associate that operation with the transaction.  </p>  <p class="simpara">   Transactions can be committed through   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::commitTransaction()}</span>, and   aborted with   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::abortTransaction()}</span>.   Transactions are also automatically aborted when the session is closed from   garbage collection or by explicitly calling   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::endSession()}</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-session.starttransaction-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <span class="simpara">      Options can be passed as argument to this method. Each element in this      options array overrides the corresponding option from the      <span class="literal">"defaultTransactionOptions"</span> option, if set when      starting the session with      <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::startSession()}</span>.     </span>     <p class="para">      </p><table class="doctable table">       <caption><strong>options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">                  <tr>          <td>maxCommitTimeMS</td>          <td>integer</td>          <td>           <span class="simpara">            The maximum amount of time in milliseconds to allow a single            <span class="literal">commitTransaction</span> command to run.           </span>           <span class="simpara">            If specified, <span class="literal">maxCommitTimeMS</span> must be a signed            32-bit integer greater than or equal to zero.           </span>          </td>         </tr>                  <tr>          <td>readConcern</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php" class="classname">MongoDB\Driver\ReadConcern</a></span></td>          <td>           <span class="simpara">            A read concern to apply to the operation.           </span>           <span class="simpara">            This option is available in MongoDB 3.2+ and will result in an            exception at execution time if specified for an older server            version.           </span>          </td>         </tr>                  <tr>          <td>readPreference</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="classname">MongoDB\Driver\ReadPreference</a></span></td>          <td>           <span class="simpara">            A read preference to use for selecting a server for the operation.           </span>          </td>         </tr>                  <tr>          <td>writeConcern</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span></td>          <td>           <span class="simpara">            A write concern to apply to the operation.           </span>          </td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-session.starttransaction-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-session.starttransaction-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-commandexception.php" class="classname">MongoDB\Driver\Exception\CommandException</a></span> if the transaction could not be started because of a server-side problem (e.g. a lock could not be obtained).</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if the transaction could not be started (e.g. a transaction was already started).</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-session.starttransaction-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.6.0</td>      <td>       <span class="simpara">        The <span class="literal">"maxCommitTimeMS"</span> option was added.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-session.starttransaction-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::startSession()} - Start a new client session for use with this client</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::commitTransaction()} - Commits a transaction</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::abortTransaction()} - Aborts a transaction</span></li>  </ul> </div></div>
 * 
     * Starts a transaction
     * @link https://secure.php.net/manual/en/mongodb-driver-session.starttransaction.php
     * @param array|object $options
     * @return void
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException On argument parsing errors
     * @throws \MongoDB\Driver\Exception\CommandException If the the transaction could not be started because of a server-side problem (e.g. a lock could not be obtained).
     * @throws \MongoDB\Driver\Exception\RuntimeException If the the transaction could not be started (e.g. a transaction was already started).
     * @since 1.4.0
     */
    final public function startTransaction(?array $options = null): void {}
}
